#include <bits/stdc++.h>
using namespace std;
using ll = long long;

vector<int> factor_exps(ll n) {
    vector<int> exps;
    if (n % 2 == 0) {
        int c = 0;
        while (n % 2 == 0) { n /= 2; ++c; }
        exps.push_back(c);
    }
    for (ll p = 3; p <= n / p; p += 2) {
        if (n % p == 0) {
            int c = 0;
            while (n % p == 0) { n /= p; ++c; }
            exps.push_back(c);
        }
    }
    if (n > 1) exps.push_back(1);
    return exps;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        ll x;
        cin >> x;
        vector<int> exps = factor_exps(x);
        // 计算 c(x)
        ll tau = 1;
        for (int e : exps) tau *= (e + 1);
        // 分层和
        int A = 0;
        for (int e : exps) A = max(A, e);
        ll layerSum = 0;
        for (int ell = 1; ell <= A; ++ell) {
            int r = 0;
            for (int e : exps) if (e >= ell) ++r;
            layerSum += (1LL << r);
        }
        cout << max(tau, layerSum) << '\n';
    }
    return 0;
}
